lab.solution:
from functools import lru_cache

@lru_cache(maxsize=None)
def ways(n):
    if n == 0:
        return 1
    if n < 0:
        return 0
    return ways(n - 1) + ways(n - 2)

assert ways(0) == 1
assert ways(1) == 1
assert ways(4) == 5
